func init() {
	eDICommunicationProfilesTable.Relations[0].Target = EDIConnectionsSchema()
	eDICommunicationProfilesTable.Relations[1].Target = EDIPartnersSchema()
	eDIConnectionsTable.Relations[0].Target = tenantdb.OrganizationsSchema()
	eDIConnectionsTable.Relations[1].Target = tenantdb.OrganizationsSchema()
	eDIConnectionsTable.Relations[2].Target = EDIPartnersSchema()
	eDIConnectionsTable.Relations[3].Target = EDIPartnersSchema()
	eDIMappingProfilesTable.Relations[0].Target = EDIPartnersSchema()
	eDIMappingProfilesTable.Relations[1].Target = EDIMappingProfileItemsSchema()
	eDIMappingProfileItemsTable.Relations[0].Target = EDIPartnersSchema()
	eDIMappingProfileItemsTable.Relations[1].Target = EDIMappingProfilesSchema()
	eDIPartnersTable.Relations[0].Target = tenantdb.OrganizationsSchema()
	eDIPartnersTable.Relations[1].Target = customerdb.CustomersSchema()
	eDIPartnersTable.Relations[2].Target = EDIConnectionsSchema()
	eDIPartnersTable.Relations[3].Target = EDICommunicationProfilesSchema()
	eDIPartnersTable.Relations[4].Target = EDIMappingProfilesSchema()
	eDIPartnersTable.Relations[5].Target = EDIMappingProfileItemsSchema()
}

